import json,os,sys
from pathlib import Path
sys.path.insert(0,'/package/forge/stage2_spec')
from new_sculpt_spec import make_spec
from validate_sculpt_spec import validate_spec
args=json.load(sys.stdin)
artifact=Path('/runtime/artifacts/sculpt-spec.json')
if sys.argv[1]=='img2threejs__create_spec':
    spec=make_spec(args['target_name'],args.get('image'))
    artifact.write_text(json.dumps(spec,indent=2))
    result={'artifact':str(artifact),'target_name':spec['targetName'],'bytes':artifact.stat().st_size}
else:
    source=Path(args['spec']).resolve()
    if not any(source.is_relative_to(Path(root)) for root in ['/package','/runtime/artifacts']): raise ValueError('Choose a package or private artifact JSON file')
    if source.stat().st_size>1000000: raise ValueError('Spec exceeds 1 MB')
    errors,warnings=validate_spec(json.loads(source.read_text()))
    result={'valid':not errors,'errors':errors,'warnings':warnings}
print(json.dumps(result))
